import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 39 · everyday recipe: creamy sausage tortellini soup (Google Trends 3/11: tortellini soup among rising dinner questions, best soup recipes)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, my granddaughter Emily called me last week and said, Grandma, everybody online is making tortellini soup, and mine came out like wallpaper paste. The pasta was mushy, the broth was gone, and the spinach was gray. I laughed, because I made the same mistakes in nineteen eighty-one, the first time I ever cooked tortellini.""",
   "creamy tortellini soup bowl spinach", "LIKE WALLPAPER PASTE")
sc("""So tonight I'm giving you my creamy sausage tortellini soup, a whole supper in one pot in thirty minutes, and the four mistakes that turn it to mush. And stay with me, because the last mistake happens the next day, and it's the reason most leftover tortellini soup gets thrown away.""",
   "pot of soup on stove kitchen", "THIRTY MINUTES")

ch("When tortellini came to Ohio")
sc("""When I was growing up in Mansfield, pasta meant spaghetti or elbow macaroni, and that was it. Then in the late seventies, the grocery store started selling fresh tortellini in the cold case, little rings of pasta stuffed with cheese. My husband said they looked like tiny hats. He was suspicious of them for about one bite.""",
   "fresh cheese tortellini package", "TINY HATS")
sc("""The Italians in Bologna have a story that tortellini were shaped like the belly button of Venus, the goddess of love. I told my husband that at the dinner table, and he turned red as a beet and didn't say another word for the rest of supper. Forty years later, my grandchildren still call them belly button soup.""",
   "handmade tortellini pasta Italy", "BELLY BUTTON SOUP")
sc("""And what I love most about this soup is that it costs about twelve dollars and feeds six people, with bread. In a minute I'll tell you how to make it with what's already in your freezer, so it's a soup you can make on a Tuesday when you thought there was nothing in the house.""",
   "family dinner table soup bowls", "TWELVE DOLLARS")

ch("What you need")
sc("""Here's what you need, honey. One pound of Italian sausage, mild or hot, out of the casings. One onion, chopped. Three cloves of garlic. One can of diced tomatoes. Six cups of chicken broth. One teaspoon of Italian seasoning. One package of cheese tortellini, about nine ounces. Three big handfuls of fresh spinach. Half a cup of heavy cream. And Parmesan cheese for the top.""",
   "Italian sausage spinach tortellini broth", "THE INGREDIENTS")
sc("""Now the tortellini. The fresh kind from the cold case, or the frozen kind, both work fine. The dried tortellini on the shelf takes much longer to cook, so if that's all you have, add five minutes. And remember the trick with the freezer I promised. A bag of frozen tortellini lasts months, and so does a pound of sausage. Keep both in the freezer, and you're always thirty minutes from supper.""",
   "frozen tortellini bag freezer", "ALWAYS IN THE FREEZER")

sc("""And pick a good pot, honey. A big heavy one, a Dutch oven if you have it, at least five quarts. A thin pot burns the sausage in one spot and leaves it raw in another, and the bottom scorches when you add the cream. My Dutch oven was a wedding present in nineteen sixty-three. It's orange, it weighs as much as a small dog, and it's made ten thousand suppers.""",
   "orange Dutch oven stove", "A WEDDING PRESENT")

ch("The base")
sc("""Step one. In a big heavy pot, brown the sausage over medium-high heat, breaking it up with a wooden spoon, until it's deep brown and a little crispy in spots. About eight minutes. Don't rush this part. Those brown bits on the bottom of the pot are where all the flavor of the soup comes from.""",
   "browning Italian sausage pot", "DEEP BROWN")
sc("""Mistake number one is pale sausage. If you just cook it until it's gray, the soup tastes like boiled meat. Let it sit still in the pot and brown. Then take out most of the grease with a spoon, but leave about a tablespoon. Add the onion, and cook it in that sausage fat for five minutes, until it's soft and golden. Then the garlic, for one minute.""",
   "onions cooking sausage fat", "NOT GRAY")
sc("""Step two. Pour in the tomatoes, the broth, and the Italian seasoning. Scrape the bottom of the pot with your spoon, to lift up all those brown bits into the broth. Bring it to a boil, then turn it down and let it simmer for ten minutes, so the flavors get to know each other. Taste it, and add salt and pepper.""",
   "scraping pot wooden spoon broth", "SCRAPE THE BOTTOM")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. And while the soup simmers, here's a little secret from my friend Rosa, whose family came from Naples. If you have the hard rind from the end of a piece of Parmesan, drop it in the pot. It melts a little and makes the broth taste rich and nutty. Take it out before serving.""",
   "parmesan rind in soup pot", "ROSA'S SECRET")

ch("The tortellini")
sc("""Step three, the tortellini. Here's mistake number two. Adding them too early. Fresh tortellini only need about three to five minutes. If you put them in at the start and let them simmer with the broth for half an hour, they swell up and split open and the cheese leaks out, and you get that wallpaper paste my granddaughter made.""",
   "split mushy tortellini soup", "THEY SPLIT OPEN")
sc("""So add the tortellini only at the very end, when the broth is done and simmering. Cook them just until they float and are tender, about four minutes. Taste one. It should be soft but still have a little chew. And keep the soup at a gentle simmer, not a hard boil. A hard boil bangs the pasta around and tears it open.""",
   "tortellini floating simmering soup", "A GENTLE SIMMER")

ch("The cream and spinach")
sc("""Step four. Turn the heat down to low. Then stir in the cream. Mistake number three is pouring cold cream into boiling soup. It can curdle and turn grainy, little white flecks floating on top. So turn the heat low first, and pour the cream in slowly while you stir. You can also warm the cream for a few seconds first.""",
   "pouring cream into soup pot", "TURN THE HEAT LOW")
sc("""Then the spinach, last of all. Just stir in the handfuls, and in about one minute, it wilts down to almost nothing. That's it. Turn off the heat. If you cook spinach any longer, it turns that sad gray-green and tastes like the bottom of a pond. Bright green spinach means you did it right.""",
   "wilting fresh spinach soup", "BRIGHT GREEN")
sc("""So far, brown the sausage dark, cook the onion in the fat, scrape the bottom, add the tortellini at the very end, then cream on low, then spinach for one minute. Ladle it into big bowls, and grate plenty of Parmesan on top, with a little black pepper. Serve it with warm crusty bread for dipping. My husband dipped until the bread was gone, then asked for more bread.""",
   "tortellini soup bowl parmesan bread", "MORE BREAD")

sc("""And here's how to make it a real supper. Put out a little bowl of extra Parmesan, a bottle of olive oil, and some red pepper flakes, so everybody can fix their own bowl. And a simple green salad on the side with a lemon dressing. Emily made it this way for her new husband's family, and his mother asked for the recipe. That's the highest compliment there is, honey.""",
   "soup dinner table salad bread", "THE HIGHEST COMPLIMENT")

ch("Making it your own")
sc("""You can change this soup a hundred ways, sweetheart. Use kale instead of spinach, but add it five minutes earlier, because kale is tougher. Use chicken sausage, or ground turkey with a teaspoon of fennel seeds. Or leave out the meat, and add a can of white beans and some sliced mushrooms. My daughter-in-law Linda makes it that way on Fridays.""",
   "kale white beans soup variations", "A HUNDRED WAYS")
sc("""And if you want it without cream, leave the cream out and stir in a spoon of pesto at the end. Or a few spoons of cream cheese, melted in. It's lighter and still creamy. For a spicy one, use hot sausage and a pinch of red pepper flakes. My grandson puts so much pepper in his, his eyes water, and he says that's the point.""",
   "pesto spoon soup bowl", "THAT'S THE POINT")

ch("The day after")
sc("""And now the last mistake I promised, the one that happens the next day. You put the leftover soup in the icebox, with the tortellini in it. Overnight, the pasta drinks up all the broth, and in the morning you have a pot of swollen, soggy pasta and no soup at all. That's mistake number four, and it's why so much of it ends up in the trash.""",
   "leftover soup container refrigerator", "NO SOUP AT ALL")
sc("""Here's the fix. If you know you'll have leftovers, cook the tortellini in a separate pot of salted water, drain them, and put them in each bowl, then ladle the hot soup over. Keep the leftover soup and the leftover pasta in separate containers. The next day, heat the soup and add the pasta for the last minute. It tastes like it was just made.""",
   "separate container pasta soup", "KEEP THEM SEPARATE")
sc("""And if it's already too late, and your pasta drank the broth, just add a cup or two of broth or water when you reheat it, and a spoon of cream. And it freezes well too, without the pasta and without the cream. Freeze the sausage and tomato broth for three months. Then thaw it, bring it to a simmer, and add fresh tortellini, cream and spinach.""",
   "frozen soup containers labeled", "FREEZE THE BROTH")

ch("Grandma's kitchen")
sc("""So one more time. Brown the sausage until it's dark. Cook the onion in the fat. Scrape the brown bits into the broth. Simmer ten minutes. Add the tortellini only at the very end, and simmer gently. Turn the heat low before the cream. Spinach for one minute. And keep the leftover pasta and soup apart. That's tortellini soup that's never mushy.""",
   "tortellini soup family dinner", "NEVER MUSHY")
sc("""Tell me in the comments, sweetheart. What's your family's favorite soup on a cold night? I'm always looking for a new one. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "warm kitchen soup pot evening", "YOUR FAVORITE SOUP?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma39", "Tortellini Soup EVERYONE Is Making (Why Yours Turns MUSHY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Tortellini, a stuffed pasta from Bologna and Modena, Italy; the legend of the navel of Venus.",
      "Recipe as written by Grandma Ruth: 1 lb Italian sausage, 1 onion, 3 garlic cloves, 1 can diced tomatoes, 6 cups chicken broth, 1 tsp Italian seasoning, 9 oz cheese tortellini, 3 handfuls spinach, 1/2 cup heavy cream, Parmesan."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
